import os
import re
from datetime import datetime
from typing import Dict, Any, List, Optional

DEFAULT_RULE_FILE = ".llmrules"

RULE_FILE_TEMPLATE = """# 🧠 GitContext: AI Architecture Memory
# AUTOGENERATED & CONTINUOUSLY SYNCED FROM GIT COMMITS.
# Feed this file to Cursor, Copilot, Claude Code, or Antigravity for instant codebase context.

## 🛠️ Tech Stack & Conventions
{conventions}

## 📐 Architecture & Coding Rules
{rules}

## 🚫 Deprecations & Anti-Patterns
{deprecations}

## 📜 Recent Architectural Changes
{recent_history}

---
*Maintained automatically by [GitContext](https://github.com/gitcontext/git-context) — Living context for AI pair programming.*
"""

class MemoryStore:
    """Manages reading, updating, and formatting of .llmrules and .cursorrules."""

    def __init__(self, repo_path: str = ".", filename: str = DEFAULT_RULE_FILE):
        self.repo_path = os.path.abspath(repo_path)
        self.file_path = os.path.join(self.repo_path, filename)

    def exists(self) -> bool:
        return os.path.isfile(self.file_path)

    def load(self) -> Dict[str, Any]:
        """Parses existing rule file into structured sections."""
        if not self.exists():
            return {
                "conventions": [],
                "rules": [],
                "deprecations": [],
                "history": []
            }

        with open(self.file_path, "r", encoding="utf-8") as f:
            content = f.read()

        conventions = self._extract_section(content, "🛠️ Tech Stack & Conventions")
        rules = self._extract_section(content, "📐 Architecture & Coding Rules")
        deprecations = self._extract_section(content, "🚫 Deprecations & Anti-Patterns")
        history = self._extract_section(content, "📜 Recent Architectural Changes")

        return {
            "conventions": conventions,
            "rules": rules,
            "deprecations": deprecations,
            "history": history
        }

    def _extract_section(self, content: str, title: str) -> List[str]:
        pattern = rf'## {re.escape(title)}\n(.*?)(?=\n## |\n---\n|$)'
        match = re.search(pattern, content, re.DOTALL)
        if not match:
            return []
        lines = match.group(1).strip().split("\n")
        items = []
        for l in lines:
            l_clean = l.strip()
            if l_clean.startswith("- "):
                items.append(l_clean[2:].strip())
            elif l_clean and not l_clean.startswith("#"):
                items.append(l_clean)
        return items

    def update(
        self,
        new_rules: List[str],
        new_conventions: List[str],
        new_deprecations: List[str],
        commit_entry: Optional[Dict[str, Any]] = None,
        max_history: int = 5
    ) -> str:
        """Appends new architectural directives and keeps rule file within token limits."""
        current = self.load()

        # Merge & deduplicate conventions
        merged_conventions = list(dict.fromkeys(current["conventions"] + new_conventions))
        # Merge & deduplicate rules
        merged_rules = list(dict.fromkeys(current["rules"] + new_rules))
        # Merge & deduplicate deprecations
        merged_deprecations = list(dict.fromkeys(current["deprecations"] + new_deprecations))

        # Update commit history log
        history = current["history"]
        if commit_entry:
            short_h = commit_entry.get("short_hash", "")
            subject = commit_entry.get("subject", "")
            summary = commit_entry.get("summary", subject)
            date_str = datetime.utcnow().strftime("%Y-%m-%d")
            history_item = f"[{short_h}] ({date_str}) {summary}"
            if history_item not in history:
                history.insert(0, history_item)

        # Cap history to max entries to preserve AI token budget
        history = history[:max_history]

        # Format markdown blocks
        conventions_md = "\n".join([f"- {c}" for c in merged_conventions]) if merged_conventions else "- Standard modern development conventions apply."
        rules_md = "\n".join([f"- {r}" for r in merged_rules]) if merged_rules else "- Follow existing module structure and patterns."
        deprecations_md = "\n".join([f"- {d}" for d in merged_deprecations]) if merged_deprecations else "- None documented."
        history_md = "\n".join([f"- {h}" for h in history]) if history else "- Initial context baseline generated."

        new_content = RULE_FILE_TEMPLATE.format(
            conventions=conventions_md,
            rules=rules_md,
            deprecations=deprecations_md,
            recent_history=history_md
        )

        with open(self.file_path, "w", encoding="utf-8") as f:
            f.write(new_content)

        return new_content
